/**
 * A count in `width` bytes (at most `max`), then that many items. Fixed-size items (`size` > 0) must fit the
 * bytes left before any is read, as in the Rust codec.
 */
export function readList<T>(r: Reader, width: number, max: number, field: string, size: number, item: () => T): T[] {
  const at = r.pos;
  const n = r.count(width, field);
  if (n > max) throw r.errAt(at, 'too_long', field);
  return readN(r, n, size, field, item);
}

/** `n` items; fixed-size items (`size` > 0) must fit the bytes left before any is read. */
export function readN<T>(r: Reader, n: number, size: number, field: string, item: () => T): T[] {
  if (size > 0 && n * size > r.remaining) throw r.err('truncated', field);
  const out: T[] = [];
  for (let i = 0; i < n; i++) out.push(item());
  return out;
}

/** Items of `size` bytes up to the end of the reader, which must hold a whole number of them. */
export function readRest<T>(r: Reader, size: number, field: string, item: () => T): T[] {
  if (r.remaining % size !== 0) throw r.err('bad_length', field);
  return readN(r, r.remaining / size, size, field, item);
}

/** Strictly ascending under `cmp`: the canonical order of keyed lists and records (§8.1, D3). */
export function strictlyAscending<T>(xs: readonly T[], cmp: (a: T, b: T) => number): boolean {
  for (let i = 1; i < xs.length; i++) if (cmp(xs[i - 1] as T, xs[i] as T) >= 0) return false;
  return true;
}

/** Compares numbers, bigints, booleans and strings (by UTF-8 bytes, D17). */
export function cmpScalar(a: number | bigint | boolean | string, b: number | bigint | boolean | string): number {
  if (typeof a === 'string' && typeof b === 'string') {
    const x = TEXT.encode(a);
    const y = TEXT.encode(b);
    const n = Math.min(x.length, y.length);
    for (let i = 0; i < n; i++) if (x[i] !== y[i]) return (x[i] as number) - (y[i] as number);
    return x.length - y.length;
  }
  const x = typeof a === 'boolean' ? Number(a) : a;
  const y = typeof b === 'boolean' ? Number(b) : b;
  return x < y ? -1 : x > y ? 1 : 0;
}

/** Compares two arrays element by element with `cmp`, then by length. */
export function cmpArray<T>(a: readonly T[], b: readonly T[], cmp: (x: T, y: T) => number): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const c = cmp(a[i] as T, b[i] as T);
    if (c !== 0) return c;
  }
  return a.length - b.length;
}

/** Compares two byte arrays. */
export function cmpBytes(a: Uint8Array, b: Uint8Array): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) if (a[i] !== b[i]) return (a[i] as number) - (b[i] as number);
  return a.length - b.length;
}

const F32 = new DataView(new ArrayBuffer(8));

/**
 * The text dump the fixtures compare: one `path=value` line per leaf, floats as their IEEE bits in
 * hexadecimal, strings JSON-escaped, bytes in hexadecimal. The Rust codec writes the same text.
 */
export class Dump {
  out = '';
  line(path: string, value: string): void {
    this.out += `${path}=${value}\n`;
  }
  int(path: string, v: number | bigint): void {
    this.line(path, String(v));
  }
  f32(path: string, v: number): void {
    F32.setFloat32(0, v, true);
    this.line(path, `f32:${F32.getUint32(0, true).toString(16).padStart(8, '0')}`);
  }
  f64(path: string, v: number): void {
    F32.setFloat64(0, v, true);
    this.line(path, `f64:${F32.getBigUint64(0, true).toString(16).padStart(16, '0')}`);
  }
  bool(path: string, v: boolean): void {
    this.line(path, v ? 'true' : 'false');
  }
  str(path: string, v: string): void {
    this.line(path, JSON.stringify(v));
  }
  bytes(path: string, v: Uint8Array): void {
    let s = 'hex:';
    for (const b of v) s += b.toString(16).padStart(2, '0');
    this.line(path, s);
  }
}

/** An action field that carries its bytes inline, or names a blob by its SHA-256 (§15.3). */
export type BlobOrBytes = { bytes: Uint8Array } | { blob: Uint8Array };

export function readBlobOrBytes(r: Reader, max: number, field: string): BlobOrBytes {
  const at = r.pos;
  const tag = r.u8(field);
  if (tag === 0) return { bytes: r.bytesOf(2, max, field) };
  if (tag === 1) return { blob: r.take(32, field).slice() };
  throw r.errAt(at, 'bad_enum', field);
}

export function writeBlobOrBytes(w: Writer, v: BlobOrBytes, max: number, field: string): void {
  if ('bytes' in v) {
    w.u8(0, field);
    w.lenBytes(v.bytes, 2, max, field);
  } else {
    if (v.blob.length !== 32) throw new EncodeError('bad_length', field);
    w.u8(1, field);
    w.bytes(v.blob);
  }
}

export function dumpBlobOrBytes(d: Dump, path: string, v: BlobOrBytes): void {
  if ('bytes' in v) d.bytes(`${path}.bytes`, v.bytes);
  else d.bytes(`${path}.blob`, v.blob);
}
